head.b:skin:
:root{--green:#04ff8e;--bg:#161616;--mut:#9b9b9b;--dim:#6f6f6f;--u:calc(100cqw/765)}
*{box-sizing:border-box;margin:0;padding:0}
body{font:500 15px/1.5 'Inter',-apple-system,'Helvetica Neue',Arial,sans-serif;background:#555;color:#fff;padding-bottom:104px;min-height:100vh}
h1{font:700 29px/1.2 'Inter',sans-serif;letter-spacing:-.3px;margin-bottom:14px}h2{font-size:20px;font-weight:700;margin:24px 0 10px;letter-spacing:-.3px}
a{color:inherit}#navbar,.Navbar{display:none}
nav{position:fixed;z-index:9;left:12px;right:12px;bottom:12px;display:flex;background:var(--bg);padding:8px;border-radius:32px;box-shadow:0 16px 30px rgba(0,0,0,.6),inset 0 1px 0 rgba(255,255,255,.12)}
nav .me{display:none}
nav a{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;font-size:11px;font-weight:600;text-decoration:none;color:var(--dim);padding:8px 2px;border-radius:24px}
nav a.on{color:#111;background:var(--green)}
nav svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.shell{container-type:inline-size;max-width:765px;margin:16px auto 0;filter:drop-shadow(0 24px 30px rgba(0,0,0,.4))}
.hd{position:relative;height:calc(200*var(--u))}
.hb{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.hb .gn{filter:drop-shadow(0 0 calc(16*var(--u)) rgba(4,255,142,.7))}
.lg{position:absolute;left:calc(114*var(--u));top:calc(34*var(--u));width:calc(72*var(--u));height:calc(72*var(--u))}
.wm{position:absolute;left:calc(202*var(--u));top:calc(34*var(--u));font:800 calc(56*var(--u))/calc(72*var(--u)) 'Figtree','Inter',sans-serif;letter-spacing:calc(-2.5*var(--u));color:var(--green)}
.wm sup{font-size:calc(20*var(--u));letter-spacing:0;vertical-align:top;line-height:1}
.tm{position:absolute;left:calc(467*var(--u));top:calc(50*var(--u));width:calc(250*var(--u));height:calc(81*var(--u));display:grid;place-items:center;color:#111;font:700 calc(33*var(--u))/1 'Inter',sans-serif;letter-spacing:calc(-.3*var(--u))}
.tm small{font-size:calc(18*var(--u));font-weight:700;vertical-align:top;position:relative;top:calc(-3*var(--u))}
.bd{background:var(--bg);margin-top:-1px;border-radius:0 0 calc(60*var(--u)) calc(60*var(--u));min-height:calc(260*var(--u));padding-bottom:calc(40*var(--u))}
#app,#blogview{padding:calc(16*var(--u)) calc(26*var(--u)) 0}
.gl{position:relative;margin:calc(-85*var(--u)) calc(-26*var(--u)) 0;height:calc(217*var(--u));border-radius:calc(58*var(--u));background:linear-gradient(180deg,#222,#181818);border:1px solid rgba(255,255,255,.2);box-shadow:0 16px 26px rgba(0,0,0,.6),inset 0 1px 0 rgba(255,255,255,.12),inset 0 -1px 0 rgba(255,255,255,.05);overflow:hidden}
.gl>*{position:absolute}
.cv{left:calc(83*var(--u));top:calc(18*var(--u));width:calc(170*var(--u));height:calc(170*var(--u));border-radius:calc(30*var(--u));background:#000;display:grid;place-items:center;color:var(--green);font:800 calc(44*var(--u)) 'Figtree',sans-serif;letter-spacing:calc(-1.5*var(--u))}
.nw{left:calc(290*var(--u));top:calc(25*var(--u));line-height:calc(38*var(--u));font-size:calc(28*var(--u));font-weight:700;color:#e6e6e6;white-space:nowrap}
.ck{left:calc(648*var(--u));top:calc(21*var(--u));width:calc(32*var(--u));height:calc(32*var(--u))}
.ly{left:calc(300*var(--u));top:calc(85*var(--u));width:calc(420*var(--u));height:calc(96*var(--u));font-size:calc(27*var(--u));font-weight:700;letter-spacing:calc(-.4*var(--u));line-height:calc(32*var(--u));-webkit-mask-image:linear-gradient(transparent 0,#000 30%,#000 70%,transparent 100%);mask-image:linear-gradient(transparent 0,#000 30%,#000 70%,transparent 100%)}
.tr{transition:transform .8s cubic-bezier(.22,.8,.28,1)}
.ln{height:calc(32*var(--u));white-space:nowrap;color:rgba(4,255,142,.4);opacity:0;transition:color .35s}.ln.near{opacity:1}.ln.on{opacity:1;color:var(--green)}.ln.on::after{content:"...."}
.tt{margin:calc(16*var(--u)) 0 0;text-align:center;font:700 calc(29*var(--u))/calc(40*var(--u)) 'Inter',sans-serif;letter-spacing:calc(-.3*var(--u))}
.ar{text-align:center;color:var(--mut);font-size:calc(24*var(--u));line-height:calc(40*var(--u));margin-top:calc(6*var(--u))}
.pr{position:relative;width:calc(604*var(--u));height:calc(20*var(--u));margin:calc(14*var(--u)) auto 0}
.pr .bar{position:absolute;left:0;right:0;top:calc(8*var(--u));margin:0;height:calc(4*var(--u))}
.pr .bar i::after{width:calc(18*var(--u));height:calc(18*var(--u));margin-top:calc(-9*var(--u));right:calc(-9*var(--u))}
.ts{display:flex;justify-content:space-between;width:calc(604*var(--u));margin:0 auto;color:var(--dim);font-size:calc(24*var(--u));line-height:calc(30*var(--u))}
.cr{display:flex;justify-content:space-between;align-items:center;width:calc(368*var(--u));margin:calc(18*var(--u)) auto 0}
.ctl{background:none;border:0;cursor:pointer;color:#6a6a6a;width:calc(48*var(--u));height:calc(48*var(--u));transition:transform .15s,filter .15s}
.ctl:hover{filter:brightness(1.4);transform:scale(1.06)}.ctl svg{width:100%;height:100%;fill:currentColor;display:block}
.ctl.play{width:calc(74*var(--u));height:calc(74*var(--u));border-radius:50%;background:var(--green);color:#111;box-shadow:0 0 calc(22*var(--u)) rgba(4,255,142,.45)}
.cn{text-align:center;margin-top:calc(22*var(--u));font-size:13px}
.card{background:linear-gradient(180deg,#222,#181818);border-radius:32px;padding:20px 22px;margin-bottom:14px;border:1px solid rgba(255,255,255,.07);box-shadow:0 16px 26px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,255,255,.12)}
.hero{border-radius:40px;padding:26px;margin-top:16px}.hero p{color:var(--mut);margin-bottom:18px}
.btn,.chip{font:inherit;font-weight:700;border:0;border-radius:99px;padding:11px 24px;background:var(--green);color:#111;cursor:pointer;text-decoration:none;display:inline-block;transition:transform .15s,filter .15s}
.btn:hover{filter:brightness(1.1);transform:scale(1.03)}
.btn.red{font-size:20px;padding:16px 34px;box-shadow:0 0 22px rgba(4,255,142,.5)}
.btn.ghost{background:transparent;border:2px solid #333;color:#fff}
.chip{padding:5px 16px;background:#2a2a2a;color:var(--mut)}.chip.ok{background:var(--green);color:#111}.chip:disabled{cursor:default}
input,select,textarea{font:inherit;width:100%;padding:12px 16px;border:1.5px solid #2c2c2c;border-radius:18px;background:#0d0d0d;color:#fff;margin-bottom:10px}
input::placeholder{color:var(--dim)}
input:focus,select:focus,.btn:focus-visible,nav a:focus-visible,.chip:focus-visible,.ctl:focus-visible{outline:2px solid var(--green);outline-offset:2px}
.row{display:flex;gap:10px}.row>*{flex:1}
.gc{display:flex;gap:14px;align-items:center;text-decoration:none;background:linear-gradient(180deg,#222,#181818);border:1px solid rgba(255,255,255,.07);border-radius:28px;padding:14px 18px;margin-bottom:10px}
.gc i{width:50px;height:50px;border-radius:18px;background:var(--green);color:#111;display:grid;place-items:center;font:800 22px 'Figtree',sans-serif}
small,.mut{color:var(--mut)}
.big{font:800 44px/1.1 'Figtree','Inter',sans-serif;letter-spacing:-1.5px;color:var(--green);margin:4px 0}
.bar{height:4px;background:#080808;border-radius:2px;margin:18px 9px 18px 0;position:relative}.bar i{display:block;height:100%;background:var(--green);border-radius:2px;position:relative;transition:width .8s}.bar i::after{content:'';position:absolute;right:-9px;top:50%;width:18px;height:18px;margin-top:-9px;border-radius:50%;background:var(--green)}
ul.l{list-style:none}ul.l li{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:11px 0;border-bottom:1px solid #2a2a2a}ul.l li:last-child{border:0}
.cols{display:grid;gap:14px}.pos{color:var(--green);font-weight:700}.neg{color:#ff6b6b;font-weight:700}
.code{font:700 22px monospace;letter-spacing:4px;color:var(--green);background:#0d0d0d;padding:4px 14px;border-radius:14px}
#blogview .post{background:linear-gradient(180deg,#222,#181818);border-radius:32px;padding:22px;margin-bottom:14px}
#blogview h3.post-title{font:700 22px 'Inter',sans-serif;margin-bottom:8px}#blogview .post-body{color:#d0d0d0}
#blogview img{max-width:100%;height:auto;border-radius:20px}.blog-pager,#blogview .post-footer{margin-top:10px;font-size:13px;color:var(--mut)}
#toast{position:fixed;left:50%;bottom:104px;transform:translateX(-50%);background:var(--green);color:#111;font-weight:700;padding:10px 20px;border-radius:99px;opacity:0;pointer-events:none;transition:opacity .2s;z-index:20;max-width:90%}#toast.on{opacity:1}
.tr.spin .ln{filter:blur(.8px)}
.ctl.play.rolling svg{animation:rl .6s linear infinite}
@keyframes rl{to{transform:rotate(360deg)}}
#ko{position:fixed;inset:0;z-index:30;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(0,0,0,.8);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
#ko.on{display:flex}
.kb{width:100%;max-width:420px;text-align:center;background:linear-gradient(180deg,#222,#181818);border:1px solid rgba(255,255,255,.12);border-radius:40px;padding:26px 22px 22px;box-shadow:0 30px 60px rgba(0,0,0,.7),0 0 40px rgba(4,255,142,.15),inset 0 1px 0 rgba(255,255,255,.12)}
.kb h2{margin:4px 0 0}
.kw{position:relative;height:216px;margin:18px 0 14px;overflow:hidden;border-radius:26px;background:#0d0d0d;-webkit-mask-image:linear-gradient(transparent 0,#000 28%,#000 72%,transparent 100%);mask-image:linear-gradient(transparent 0,#000 28%,#000 72%,transparent 100%)}
.kz{position:absolute;left:10px;right:10px;top:72px;height:72px;border:2px solid var(--green);border-radius:22px;box-shadow:0 0 22px rgba(4,255,142,.35),inset 0 0 18px rgba(4,255,142,.12);z-index:1;pointer-events:none}
.kr{will-change:transform}
.ki{height:72px;line-height:72px;font-size:28px;font-weight:700;color:#6f6f6f;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:0 24px;transition:color .3s,transform .3s}
.kr.go .ki{filter:blur(1px)}
.ki.win{color:var(--green);transform:scale(1.12)}
@media(max-width:899px){
body{padding-bottom:96px}
.shell{display:flex;flex-direction:column;min-height:calc(100vh - 16px - 96px);min-height:calc(100dvh - 16px - 96px)}
.bd{flex:1}}
@media(min-width:900px){
body{padding:0 0 40px 264px}
nav{top:16px;bottom:16px;left:16px;width:232px;right:auto;flex-direction:column;padding:26px 14px;gap:6px;border-radius:40px}
nav .me{display:block;margin-top:auto;color:var(--dim);font-size:12px;padding:10px;word-break:break-all}
nav a{flex:0;flex-direction:row;gap:14px;font-size:15px;padding:12px 16px}
#toast{bottom:28px}.cols{grid-template-columns:1fr 1fr}.shell{margin-top:32px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important}}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
import {initializeApp} from "https://www.gstatic.com/firebasejs/10.14.1/firebase-app.js";
import {getAnalytics} from "https://www.gstatic.com/firebasejs/10.14.1/firebase-analytics.js";
import {getAuth,GoogleAuthProvider,signInWithPopup,signOut,onAuthStateChanged} from "https://www.gstatic.com/firebasejs/10.14.1/firebase-auth.js";
import {getFirestore,doc,getDoc,getDocs,setDoc,collection,writeBatch,serverTimestamp,onSnapshot,addDoc,deleteDoc} from "https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore.js";

const DEF={apiKey:"AIzaSyCPLSsh4vY7jyXQUrPXyOdOMUwEy0yyzJo",authDomain:"arisanpatungan.firebaseapp.com",projectId:"arisanpatungan",storageBucket:"arisanpatungan.firebasestorage.app",messagingSenderId:"992139030932",appId:"1:992139030932:web:ee797771d20f24d5b81f81",measurementId:"G-9G3852TFNY"};
const SUPER="penjualamanah2020@gmail.com";
const cfg=DEF;
const app=initializeApp(cfg),auth=getAuth(app),db=getFirestore(app);
try{getAnalytics(app)}catch(e){}

const $=s=>document.querySelector(s),A=()=>$('#app');
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const rp=n=>'Rp'+Math.round(n||0).toLocaleString('id-ID');
const TY={arisan:'Arisan',patungan:'Patungan',celengan:'Celengan bersama'};
let U=null,G=[],D={},subs=[],tt;
const isSuper=()=>U&&U.email===SUPER;
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('on');clearTimeout(tt);tt=setTimeout(()=>e.classList.remove('on'),2800)}
function unsub(){subs.forEach(f=>f());subs=[];D={m:[],r:[],p:[],e:[],c:[]}}
unsub();

/* ---------- auth ---------- */
onAuthStateChanged(auth,async u=>{
  U=u;$('#me').innerHTML=u?`<b style="color:#fff">${esc(u.displayName||'')}</b><br/>${esc(u.email)}<br/>${u.email===SUPER?'Superadmin':'Pengguna'}`:'';
  if(u){try{await setDoc(doc(db,'users',u.uid),{name:u.displayName||'',email:u.email,photo:u.photoURL||''},{merge:true});await loadG()}catch(e){toast(e.code||e.message)}}
  else G=[];
  route();
});
async function loadG(){const s=await getDocs(collection(db,'users',U.uid,'myGroups'));G=s.docs.map(d=>({id:d.id,...d.data()}))}

/* ---------- router ---------- */
addEventListener('hashchange',route);
function route(){
  unsub();
  let v=location.hash.replace('#/','');
  if(!v)v=document.body.dataset.page==='index'?'home':'panduan';
  const base=v.split('/')[0];
  document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('on',a.dataset.r===(base==='g'||base==='join'?'grup':base)));
  $('#blogview').style.display=base==='panduan'?'block':'none';
  A().style.display='block';
  if(base==='panduan'){A().innerHTML=guide();return}
  if(base==='akun')return vAkun();
  if(!U&&base!=='home')return gate();
  if(base==='g')return openGroup(v.split('/')[1]);
  if(base==='grup')return vGrup('');
  if(base==='join')return vGrup(v.split('/')[1]||'');
  if(base==='aktivitas')return vAkt();
  vHome();
}

/* ---------- views ---------- */
function gate(){A().innerHTML=`<div class="card hero"><h1>Arisan dan patungan tanpa ribet</h1><p>Masuk dengan Google untuk membuat grup atau bergabung dengan kode dari temanmu.</p><button class="btn" data-act="login">Masuk dengan Google</button></div>`}
function glist(){return G.length?G.map(g=>`<a class="gc" href="#/g/${g.id}"><i>${esc((g.name||'?')[0].toUpperCase())}</i><div><b>${esc(g.name)}</b><br/><small>${TY[g.type]||''}</small></div></a>`).join(''):`<p class="mut">Belum ada grup. Buat grup pertamamu di menu Grup.</p>`}
function vHome(){
  A().innerHTML=`<div class="gl"><div class="cv" id="dcv"></div><div class="nw" id="dnw"></div><svg class="ck" viewBox="0 0 32 32"><circle cx="16" cy="16" r="16" fill="#04ff8e"/><path d="M9 16.5l4.8 4.8L23 11.5" stroke="#161616" stroke-width="3.2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="ly"><div class="tr" id="dtr"></div></div></div><h2 class="tt" id="dn"></h2><p class="ar" id="ds"></p><div class="pr"><div class="bar"><i id="dbi"></i></div></div><div class="ts"><span id="dt1"></span><span id="dt2"></span></div><div class="cr"><button class="ctl" data-act="dprev" aria-label="Grup sebelumnya"><svg viewBox="0 0 48 48"><rect x="0" y="2" width="8" height="44" rx="2"/><path d="M45 6v36L12 24z" stroke="currentColor" stroke-width="4" stroke-linejoin="round"/></svg></button><button class="ctl play" data-act="dgo" aria-label="Kocok"><svg viewBox="0 0 74 74"><rect x="20" y="20" width="34" height="34" rx="9" fill="none" stroke="currentColor" stroke-width="4"/><circle cx="29" cy="29" r="3.4"/><circle cx="37" cy="37" r="3.4"/><circle cx="45" cy="45" r="3.4"/></svg></button><button class="ctl" data-act="dnext" aria-label="Grup berikutnya"><svg viewBox="0 0 48 48"><rect x="40" y="2" width="8" height="44" rx="2"/><path d="M3 6v36l33-18z" stroke="currentColor" stroke-width="4" stroke-linejoin="round"/></svg></button></div><p class="mut cn">Ini data contoh. Ketuk tombol hijau untuk mengocok, panah untuk ganti grup.</p>`+(U?`<h2>Grup saya</h2>${glist()}`:`<div class="card hero"><h2 style="margin-top:0">Siap bikin grup sendiri?</h2><p>Masuk dengan Google untuk membuat arisan, patungan, atau celengan bersama.</p><button class="btn" data-act="login">Masuk dengan Google</button></div>`);
  paint();
}
function vGrup(code){A().innerHTML=`<h1>Grup</h1><div class="cols"><form class="card" data-form="new"><b>Buat grup baru</b><br/><br/><input name="name" placeholder="Nama grup" required maxlength="60"/><select name="type"><option value="arisan">Arisan</option><option value="patungan">Patungan</option><option value="celengan">Celengan bersama</option></select><div class="row"><input name="iuran" type="number" inputmode="numeric" placeholder="Iuran (Rp)"/><select name="periode"><option>mingguan</option><option selected="selected">bulanan</option></select></div><input name="target" type="number" inputmode="numeric" placeholder="Target (khusus celengan)"/><button class="btn">Buat grup</button></form><form class="card" data-form="join"><b>Gabung dengan kode</b><br/><br/><input name="code" placeholder="Kode grup" value="${esc(code)}" required="required"/><button class="btn">Gabung</button></form></div><h2>Grup saya</h2>${glist()}`}
async function vAkt(){
  A().innerHTML=`<h1>Aktivitas</h1><p class="mut">Memuat...</p>`;let all=[];
  for(const g of G){if(g.type!=='arisan')continue;try{const s=await getDocs(collection(db,'groups',g.id,'rounds'));s.forEach(d=>all.push({g:g.name,...d.data()}))}catch(e){}}
  all.sort((a,b)=>(b.date?.seconds||0)-(a.date?.seconds||0));
  A().innerHTML=`<h1>Aktivitas</h1>`+(all.length?`<div class="card"><ul class="l">${all.map(r=>`<li><span><b>${esc(r.winnerName)}</b> dapat giliran ke-${r.n}<br/><small>${esc(r.g)}</small></span><b>${rp(r.pot)}</b></li>`).join('')}</ul></div>`:`<p class="mut">Belum ada kocokan. Hasil kocok akan muncul di sini.</p>`);
}
async function vAkun(){
  let h=`<h1>Akun</h1>`;
  if(U)h+=`<div class="card"><b>${esc(U.displayName)}</b>${isSuper()?' <span class="chip ok">Superadmin</span>':''}<br/><small>${esc(U.email)}</small><br/><br/><button class="btn ghost" data-act="logout">Keluar</button></div>`;
  else h+=`<div class="card"><button class="btn" data-act="login">Masuk dengan Google</button></div>`;
  h+=`<div id="sa"></div>`;
  A().innerHTML=h;
  if(isSuper()){try{const s=await getDocs(collection(db,'groups'));$('#sa').innerHTML=`<h2>Semua grup (${s.size})</h2><div class="card"><ul class="l">${s.docs.map(d=>{const x=d.data();return `<li><span>${esc(x.name)}<br/><small>${TY[x.type]||''} - ${esc(d.id)}</small></span><a href="#/g/${d.id}">Buka</a></li>`}).join('')}</ul></div>`}catch(e){toast(e.code)}}
}

/* ---------- detail grup ---------- */
function openGroup(gid){
  D.gid=gid;A().innerHTML=`<p class="mut">Memuat...</p>`;
  const er=e=>toast(e.code||e.message);
  subs.push(onSnapshot(doc(db,'groups',gid),s=>{
    if(!s.exists()){A().innerHTML=`<p>Grup tidak ditemukan.</p>`;return}
    const first=!D.g;D.g={id:gid,...s.data()};
    if(first){
      const sub=(k,p)=>subs.push(onSnapshot(collection(db,'groups',gid,p),q=>{D[k]=q.docs.map(d=>({id:d.id,...d.data()}));draw()},er));
      sub('m','members');
      if(D.g.type==='arisan'){sub('r','rounds');sub('p','payments')}
      if(D.g.type==='patungan')sub('e','expenses');
      if(D.g.type==='celengan')sub('c','contribs');
    }
    draw();
  },er));
}
const isAdm=()=>isSuper()||(D.m.find(x=>x.id===U.uid)||{}).role==='admin';
function draw(){
  const g=D.g;if(!g||!U)return;if(document.activeElement&&document.activeElement.closest('form'))return;
  const adm=isAdm(),m=D.m;
  let h=`<a href="#/grup" class="mut">&larr; Semua grup</a><h1>${esc(g.name)}</h1><p class="mut">${TY[g.type]} - ${rp(g.iuran)} ${esc(g.periode||'')} - ${m.length} anggota</p>`;
  if(adm)h+=`<div class="card">Kode undangan <span class="code">${esc(g.code)}</span> <button class="btn ghost" data-act="copy">Salin link</button></div>`;
  if(g.type==='arisan'){
    const n=D.r.length+1,left=m.filter(x=>!x.hasWon),won=D.r.slice().sort((a,b)=>a.n-b.n),pot=g.iuran*m.length;
    h+=`<div class="card"><small>Putaran berikutnya: ke-${Math.min(n,m.length)}</small><div class="big">${rp(pot)}</div><div class="bar"><i style="width:${m.length?D.r.length/m.length*100:0}%"></i></div><small>${D.r.length} dari ${m.length} putaran selesai</small>${adm&&left.length?`<br/><br/><button class="btn red" data-act="kocok">Kocok sekarang</button>`:''}${!left.length&&m.length?`<br/><br/><b>Semua anggota sudah dapat. Arisan selesai.</b>`:''}</div>
    <div class="cols"><div class="card"><b>Belum dapat (${left.length})</b><ul class="l">${left.map(x=>`<li>${esc(x.name)}</li>`).join('')}</ul></div>
    <div class="card"><b>Sudah dapat (${won.length})</b><ul class="l">${won.map(r=>`<li><span>${esc(r.winnerName)}</span><small>ke-${r.n}</small></li>`).join('')}</ul></div></div>
    <h2>Status bayar putaran ke-${n}</h2><div class="card"><ul class="l">${m.map(x=>{const ok=(D.p.find(p=>p.id===n+'_'+x.id)||{}).status==='lunas';return `<li><span>${esc(x.name)}</span><button class="chip ${ok?'ok':''}" data-act="pay" data-id="${x.id}" ${adm?'':'disabled="disabled"'}>${ok?'Lunas':'Belum'}</button></li>`}).join('')}</ul></div>`;
  }
  if(g.type==='patungan'){
    const bal={};m.forEach(x=>bal[x.id]=0);
    D.e.forEach(e=>{if(bal[e.paidBy]!==undefined)bal[e.paidBy]+=e.amount;const w=(e.splitWith||[]).filter(i=>bal[i]!==undefined);w.forEach(i=>bal[i]-=e.amount/w.length)});
    h+=`<form class="card" data-form="exp"><b>Catat pengeluaran (dibagi rata)</b><br/><br/><input name="title" placeholder="Untuk apa?" required="required"/><input name="amount" type="number" inputmode="numeric" placeholder="Jumlah (Rp)" required="required"/><button class="btn">Catat</button></form>
    <h2>Saldo</h2><div class="card"><ul class="l">${m.map(x=>`<li><span>${esc(x.name)}</span><span class="${bal[x.id]>=0?'pos':'neg'}">${bal[x.id]>=0?'piutang ':'utang '}${rp(Math.abs(bal[x.id]))}</span></li>`).join('')}</ul></div>
    <h2>Pengeluaran</h2><div class="card"><ul class="l">${D.e.map(e=>`<li><span>${esc(e.title)}<br/><small>dibayar ${esc(e.paidByName)}</small></span><span>${rp(e.amount)} ${e.paidBy===U.uid||adm?`<button class="chip" data-act="delx" data-id="${e.id}">Hapus</button>`:''}</span></li>`).join('')||'<li class="mut">Belum ada.</li>'}</ul></div>`;
  }
  if(g.type==='celengan'){
    const tot=D.c.reduce((s,c)=>s+c.amount,0),per={};D.c.forEach(c=>per[c.uid]=(per[c.uid]||0)+c.amount);
    h+=`<div class="card"><small>Terkumpul</small><div class="big">${rp(tot)}</div>${g.target?`<div class="bar"><i style="width:${Math.min(100,tot/g.target*100)}%"></i></div><small>Target ${rp(g.target)}</small>`:''}</div>
    <form class="card" data-form="con"><b>Setor ke celengan</b><br/><br/><input name="amount" type="number" inputmode="numeric" placeholder="Jumlah (Rp)" required="required"/><button class="btn">Setor</button></form>
    <h2>Per anggota</h2><div class="card"><ul class="l">${m.map(x=>`<li><span>${esc(x.name)}</span><b>${rp(per[x.id])}</b></li>`).join('')}</ul></div>`;
  }
  if(g.type==='arisan'&&D.r.length)h+=`<h2>Riwayat kocokan</h2><div class="card"><ul class="l">${D.r.slice().sort((a,b)=>b.n-a.n).map(r=>`<li><span>Ke-${r.n}: <b>${esc(r.winnerName)}</b></span><b>${rp(r.pot)}</b></li>`).join('')}</ul></div>`;
  A().innerHTML=h;
}

/* ---------- aksi ---------- */
function hideKocok(){const o=document.getElementById('ko');if(o)o.classList.remove('on')}
function showKocok(names,win,n){
  return new Promise(res=>{
    let o=document.getElementById('ko');
    if(!o){o=document.createElement('div');o.id='ko';document.body.appendChild(o)}
    const H=72,N=30,F=[];
    for(let k=0;k<N;k++)F.push(pick(names,k?F[k-1]:win));
    if(names.length>1&&F[N-1]===win)F[N-1]=pick(names,win);
    const items=F.concat(win,pick(names,win));
    o.innerHTML=`<div class="kb" role="dialog" aria-live="polite"><small>Putaran ke-${n}</small><h2 id="kh">Mengocok...</h2><div class="kw"><div class="kz"></div><div class="kr go" id="kr">${items.map(x=>`<div class="ki">${esc(x)}</div>`).join('')}</div></div><small id="kf">Tunggu sebentar</small></div>`;
    o.classList.add('on');
    const kr=document.getElementById('kr'),dur=RM()?0:4200;
    kr.style.transition='none';kr.style.transform='translateY('+H+'px)';void kr.offsetHeight;
    kr.style.transition=dur?'transform '+dur+'ms cubic-bezier(.12,.62,.1,1)':'none';
    kr.style.transform='translateY('+(-(N-1)*H)+'px)';
    setTimeout(()=>{
      kr.classList.remove('go');kr.children[N].classList.add('win');
      document.getElementById('kh').textContent='Pemenang!';
      document.getElementById('kf').textContent='Selamat, '+win;
      if(navigator.vibrate)navigator.vibrate([40,40,80]);
      setTimeout(res,RM()?300:2000);
    },dur+60);
  });
}
addEventListener('click',async e=>{
  const t=e.target.closest('[data-act]');if(!t)return;const a=t.dataset.act,g=D.g;
  try{
    if(a==='login')await signInWithPopup(auth,new GoogleAuthProvider());
    if(a==='logout'){await signOut(auth);location.hash='#/akun'}
    if(a==='copy'){await navigator.clipboard.writeText(location.origin+'/#/join/'+g.code);toast('Link undangan disalin')}
    if(a==='pay'){const n=D.r.length+1,id=n+'_'+t.dataset.id,ok=(D.p.find(p=>p.id===id)||{}).status==='lunas';await setDoc(doc(db,'groups',g.id,'payments',id),{round:n,uid:t.dataset.id,status:ok?'belum':'lunas'})}
    if(a==='delx')await deleteDoc(doc(db,'groups',g.id,'expenses',t.dataset.id));
    if(a==='kocok'){
      if(KB)return;
      const left=D.m.filter(x=>!x.hasWon);if(!left.length)return;
      if(!confirm('Kocok pemenang putaran ke-'+(D.r.length+1)+'? Hasil tidak bisa diubah.'))return;
      const r=new Uint32Array(1);crypto.getRandomValues(r);const w=left[r[0]%left.length],n=D.r.length+1;
      KB=true;
      try{
        await showKocok(D.m.map(x=>x.name),w.name,n);
        const b=writeBatch(db);
        b.set(doc(db,'groups',g.id,'rounds',String(n)),{n,winnerId:w.id,winnerName:w.name,date:serverTimestamp(),pot:g.iuran*D.m.length});
        b.update(doc(db,'groups',g.id,'members',w.id),{hasWon:true});
        await b.commit();toast('Pemenang: '+w.name);
      }finally{KB=false;hideKocok()}
    }
  }catch(err){toast(err.code||err.message)}
});

addEventListener('submit',async e=>{
  const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();
  const v=Object.fromEntries(new FormData(f)),k=f.dataset.form,g=D.g;
  try{
    if(k==='new'){
      const gid=doc(collection(db,'groups')).id,code=Math.random().toString(36).slice(2,8).toUpperCase(),b=writeBatch(db);
      b.set(doc(db,'groups',gid),{name:v.name.trim(),type:v.type,ownerId:U.uid,iuran:+v.iuran||0,periode:v.periode,target:+v.target||0,status:'aktif',code,createdAt:serverTimestamp()});
      b.set(doc(db,'groups',gid,'members',U.uid),{name:U.displayName||U.email,photo:U.photoURL||'',role:'admin',hasWon:false,joinedAt:serverTimestamp()});
      b.set(doc(db,'joinCodes',code),{gid,name:v.name.trim(),type:v.type});
      b.set(doc(db,'users',U.uid,'myGroups',gid),{name:v.name.trim(),type:v.type});
      await b.commit();await loadG();location.hash='#/g/'+gid;
    }
    if(k==='join'){
      const code=v.code.trim().toUpperCase(),s=await getDoc(doc(db,'joinCodes',code));
      if(!s.exists())return toast('Kode tidak ditemukan');
      const j=s.data();if(G.some(x=>x.id===j.gid)){location.hash='#/g/'+j.gid;return}
      const b=writeBatch(db);
      b.set(doc(db,'groups',j.gid,'members',U.uid),{name:U.displayName||U.email,photo:U.photoURL||'',role:'member',hasWon:false,code,joinedAt:serverTimestamp()});
      b.set(doc(db,'users',U.uid,'myGroups',j.gid),{name:j.name,type:j.type||'arisan'});
      await b.commit();await loadG();location.hash='#/g/'+j.gid;
    }
    if(k==='exp'){await addDoc(collection(db,'groups',g.id,'expenses'),{title:v.title.trim(),amount:+v.amount,paidBy:U.uid,paidByName:U.displayName||U.email,splitWith:D.m.map(x=>x.id),date:serverTimestamp()});f.reset();document.activeElement.blur();draw()}
    if(k==='con'){await addDoc(collection(db,'groups',g.id,'contribs'),{uid:U.uid,amount:+v.amount,date:serverTimestamp()});f.reset();document.activeElement.blur();draw()}
  }catch(err){toast(err.code||err.message)}
});

const guide=()=>`<h1>Panduan</h1><div class="card"><b>Cara pakai</b><ul class="l"><li>1. Masuk dengan Google.</li><li>2. Buat grup di menu Grup, atau gabung dengan kode dari temanmu.</li><li>3. Admin membagikan kode undangan dari halaman grup.</li><li>4. Admin menekan Kocok tiap putaran. Hasilnya terkunci.</li><li>5. Admin menandai siapa yang sudah bayar.</li></ul></div>${isSuper()?'<p class="mut">Artikel panduan dari blog tampil di bawah ini. Tulis lewat Blogger, menu Postingan, Postingan baru.</p>':''}`;
const mk=()=>[
{u:0,n:'Arisan Geng Kantor',s:'Rp500.000 per bulan - 12 anggota',b:'ARISAN',tot:12,v:7,L:['Putaran 5: Rina','Putaran 6: Dimas','Putaran 7: Sinta'],P:['Budi','Ayu','Joko','Maya','Tono']},
{u:1,n:'Patungan Liburan Bali',s:'Dibagi rata - 5 orang',b:'PATUNGAN',tot:4000000,v:1750000,L:['Tiket pesawat: Rp1.500.000','Penginapan: Rp250.000'],P:[['Sewa motor: Rp300.000',300000],['Makan malam: Rp240.000',240000],['Tiket masuk: Rp180.000',180000],['Bensin: Rp90.000',90000]]},
{u:1,n:'Celengan Kado Nikahan',s:'Target Rp3.000.000',b:'CELENGAN',tot:3000000,v:1200000,L:['Rina setor Rp500.000','Budi setor Rp700.000'],P:[['Ayu setor Rp250.000',250000],['Joko setor Rp400.000',400000],['Maya setor Rp300.000',300000]]}];
let DS=mk(),dm=0;
function paint(){
  const d=DS[dm],i=d.L.length-1,ar=!d.u,tr=$('#dtr');
  tr.style.transition='none';
  tr.style.transform='translateY(calc('+(1-i)+'*32*var(--u)))';
  tr.innerHTML=d.L.map((x,k)=>`<p class="ln${k==i?' on':k==i-1?' near':''}">${esc(x)}</p>`).join('')+`<p class="ln near">${d.P.length?'Kocok berikutnya':'Selesai'}</p>`;
  $('#dcv').textContent=ar?d.v+'/'+d.tot:Math.round(d.v/d.tot*100)+'%';
  $('#dnw').textContent='\u2022 '+d.b;$('#dn').textContent=d.n;$('#ds').textContent=d.s;
  $('#dbi').style.width=Math.min(100,d.v/d.tot*100)+'%';
  $('#dt1').textContent=ar?'Putaran '+d.v:rp(d.v);$('#dt2').textContent=ar?d.tot+' putaran':rp(d.tot);
  void tr.offsetHeight;tr.style.transition='';
}
let busy=false,KB=false;
const RM=()=>matchMedia('(prefers-reduced-motion:reduce)').matches;
const pick=(a,not)=>{let c;do{c=a[Math.floor(Math.random()*a.length)]}while(a.length>1&&c===not);return c};
function dgo(){
  if(busy)return;
  const d=DS[dm];if(!d.P.length)return toast('Contoh ini sudah selesai. Coba grup lain.');
  const p=d.P.splice(Math.floor(Math.random()*d.P.length),1)[0];
  const nm=x=>d.u?x[0]:x,fin=d.u?p[0]:'Putaran '+(d.v+1)+': '+p;
  const pool=d.P.map(nm).concat(nm(p)),F=[];
  for(let k=0;k<18;k++)F.push(pick(pool,F[k-1]));
  const tr=$('#dtr'),i0=d.L.length-1,fi=d.L.length+F.length;
  const items=d.L.concat(F,[fin,d.P.length?'Kocok berikutnya':'Selesai']);
  tr.style.transition='none';
  tr.innerHTML=items.map((x,k)=>`<p class="ln${k===i0?' on':k>=i0-1?' near':''}">${esc(x)}</p>`).join('');
  tr.style.transform='translateY(calc('+(1-i0)+'*32*var(--u)))';
  tr.classList.add('spin');void tr.offsetHeight;
  const dur=RM()?0:2800;
  tr.style.transition=dur?'transform '+dur+'ms cubic-bezier(.15,.6,.1,1)':'none';
  tr.style.transform='translateY(calc('+(1-fi)+'*32*var(--u)))';
  busy=true;$('.ctl.play').classList.add('rolling');
  setTimeout(()=>{
    tr.classList.remove('spin');tr.children[fi].classList.add('on');
    setTimeout(()=>{
      if(d.u){d.L.push(p[0]);d.v+=p[1]}else{d.v++;d.L.push(fin)}
      paint();busy=false;$('.ctl.play').classList.remove('rolling');
      if(navigator.vibrate)navigator.vibrate(30);
    },RM()?0:450);
  },dur+30);
}
addEventListener('click',e=>{const t=e.target.closest('.ctl');if(!t)return;const a=t.dataset.act;
  if(busy)return;
  if(a==='dgo')dgo();if(a==='dprev'||a==='dnext'){dm=(dm+(a==='dnext'?1:2))%3;paint()}});
function clk(){const d=new Date(),h=d.getHours();$('#clk').innerHTML=(h%12||12)+':'+String(d.getMinutes()).padStart(2,'0')+'<small>'+(h<12?'AM':'PM')+'</small>'}
clk();setInterval(clk,10000);
//
